spec_before:
test('issues a refund', async ({ page }) => {
  await page.goto('/payments/9001');
  await page.getByRole('button', { name: 'Refund' }).click();
  await page.waitForResponse((r) => r.url().includes('/api/refunds') && r.ok()).catch(() => {});
  await expect(page.getByRole('dialog')).toBeHidden();
});
